/**
 * Referrer host suffixes and their brand keys, most specific first (gemini.google.com before google).
 *
 * @return string[]
 */
function swiftdash_referrer_hosts() {
	return array(
		'gemini.google.com'       => 'googlegemini',
		'bard.google.com'         => 'googlegemini',
		'chatgpt.com'             => 'openai',
		'openai.com'              => 'openai',
		'perplexity.ai'           => 'perplexity',
		'claude.ai'               => 'claude',
		'anthropic.com'           => 'claude',
		'copilot.microsoft.com'   => 'copilot',
		'copilot.cloud.microsoft' => 'copilot',
		'deepseek.com'            => 'deepseek',
		'meta.ai'                 => 'meta',
		'grok.com'                => 'grok',
		'mistral.ai'              => 'mistralai',
		'you.com'                 => 'you',
		'phind.com'               => 'phind',
		'duckduckgo.com'          => 'duckduckgo',
		'facebook.com'            => 'facebook',
		'fb.com'                  => 'facebook',
		'instagram.com'           => 'instagram',
		'x.com'                   => 'x',
		'twitter.com'             => 'x',
		't.co'                    => 'x',
		'linkedin.com'            => 'linkedin',
		'lnkd.in'                 => 'linkedin',
		'reddit.com'              => 'reddit',
		'youtube.com'             => 'youtube',
		'youtu.be'                => 'youtube',
		'tiktok.com'              => 'tiktok',
		'github.com'              => 'github',
		'news.ycombinator.com'    => 'ycombinator',
	);
}

/**
 * Brand key of a referrer host, or '' when unknown.
 *
 * @param string $host Referrer host.
 * @return string
 */
function swiftdash_referrer_brand( $host ) {
	$host  = preg_replace( '/^www\./', '', strtolower( $host ) );
	$hosts = swiftdash_referrer_hosts();
	foreach ( $hosts as $suffix => $brand ) {
		if ( $host === $suffix || str_ends_with( $host, '.' . $suffix ) ) {
			return $brand;
		}
	}
	// Country domains: google.co.uk, search.yahoo.com, pinterest.de, bing.com.
	if ( preg_match( '/(?:^|\.)(google|bing|yahoo|pinterest)\.[a-z.]+$/', $host, $m ) ) {
		return $m[1];
	}
	return '';
}

/**
 * Brand key of an AI traffic source key (swiftdash_ai_sources()), or '' when unknown.
 *
 * @param string $source Source key.
 * @return string
 */
function swiftdash_ai_brand( $source ) {
	$map = array(
		'chatgpt' => 'openai',
		'gemini'  => 'googlegemini',
		'mistral' => 'mistralai',
	);
	$key = isset( $map[ $source ] ) ? $map[ $source ] : $source;
	return isset( swiftdash_brands()[ $key ] ) ? $key : '';
}

/**
 * Print a brand icon tile: the brand mark in its color on a soft tint, the first letter for
 * brands without a mark, or a question mark in a neutral circle for unknown sources.
 *
 * @param string $key Brand key or ''.
 */
function swiftdash_render_brand_tile( $key ) {
	$brands = swiftdash_brands();
	if ( ! isset( $brands[ $key ] ) ) {
		echo '<span class="sd-in-row__icon sd-brand sd-brand--unknown" aria-hidden="true">?</span>';
		return;
	}
	list( $name, $hex, $path ) = $brands[ $key ];
	printf( '<span class="sd-in-row__icon sd-brand" style="--sd-brand: #%s" aria-hidden="true">', esc_attr( $hex ) );
	if ( '' !== $path ) {
		printf( '<svg class="sd-icon" viewBox="0 0 24 24" focusable="false"><path fill="currentColor" d="%s"/></svg>', esc_attr( $path ) );
	} else {
		echo '<span class="sd-brand__letter">' . esc_html( mb_substr( $name, 0, 1 ) ) . '</span>';
	}
	echo '</span>';
}
